<form method="POST" action="{{ $editing ? route('web.departments.update',$department) : route('web.departments.store') }}" class="space-y-5">@csrf @if($editing) @method('PUT') @endif<div class="rounded-lg border bg-background p-5 shadow-sm"><div class="grid gap-4 sm:grid-cols-2"><label>Name<input required name="name" value="{{ old('name',$department->name ?? '') }}" class="mt-1 h-10 w-full rounded border px-3"></label><label>Code<input name="code" value="{{ old('code',$department->code ?? '') }}" class="mt-1 h-10 w-full rounded border px-3"></label><label>Department head<select name="head_staff_id" class="mt-1 h-10 w-full rounded border px-3"><option value="">Unassigned</option>@foreach($staff as $member)<option value="{{ $member->id }}" @selected((string)old('head_staff_id',$department->head_staff_id ?? '')===(string)$member->id)>{{ $member->full_name }}</option>@endforeach</select></label><label>Status<select name="status" class="mt-1 h-10 w-full rounded border px-3">@foreach(['Active','Inactive'] as $status)<option value="{{ $status }}" @selected(old('status',$department->status ?? 'Active')===$status)>{{ $status }}</option>@endforeach</select></label><label class="sm:col-span-2">Description<textarea name="description" class="mt-1 min-h-28 w-full rounded border p-3">{{ old('description',$department->description ?? '') }}</textarea></label></div></div><div class="flex justify-end gap-3"><a href="{{ $editing ? route('web.departments.show',$department) : route('web.departments.index') }}" class="inline-flex h-10 items-center rounded border px-4 text-sm">Cancel</a><button class="inline-flex h-10 items-center rounded bg-primary px-4 text-sm text-white">{{ $editing?'Save changes':'Create department' }}</button></div></form>
